bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
docker exec -i "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';import pg from 'pg';
const pool=new pg.Pool({host:process.env.VIDEOBOT_DB_HOST,user:process.env.VIDEOBOT_DB_USER,database:process.env.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1,connectionTimeoutMillis:4500});
let code=100;
try{
 const {rows:[r]}=await pool.query(`
 WITH paid AS (
 SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL
 ), receipts AS (
 SELECT delivery_key,listing_id,topic_id,sale_mode,status,paid_message_id FROM videobot_post_receipts
 ), totals AS (
 SELECT
 (SELECT COUNT(*) FROM paid) paid_keys,
 (SELECT COUNT(*) FROM paid p JOIN receipts r USING(delivery_key)) covered_paid_keys,
 (SELECT COUNT(DISTINCT topic_id) FROM receipts) topic_count,
 (SELECT COUNT(*) FROM receipts r WHERE NOT EXISTS(SELECT 1 FROM paid p WHERE p.delivery_key=r.delivery_key)) unpurchased_receipts,
 (SELECT COUNT(*) FROM receipts r JOIN paid p USING(delivery_key) WHERE status='sent' AND paid_message_id IS NOT NULL) valid_protected_receipts,
 (SELECT COUNT(*) FROM receipts r JOIN paid p USING(delivery_key) WHERE sale_mode='paid_media') native_protected,
 (SELECT COUNT(*) FROM receipts r WHERE paid_message_id=4718) known4718,
 (SELECT COUNT(*) FROM receipts r WHERE sale_mode='invoice') invoice_receipts
 )
 SELECT * FROM totals`);
 const n=k=>Number(r[k]);
 if(n('paid_keys')===1)code|=1;
 if(n('paid_keys')>1)code|=2;
 if(n('paid_keys')===n('covered_paid_keys'))code|=4;
 if(n('topic_count')===1)code|=8;
 if(n('unpurchased_receipts')>0)code|=16;
 if(n('valid_protected_receipts')===n('paid_keys'))code|=32;
 if(n('native_protected')===n('paid_keys'))code|=64;
 if(n('known4718')>0)code|=128;
}finally{await pool.end()}
process.exit(code);
NODE
